import { format } from "prettier";
// Embed local browser assets so Vercel's server bundler needs no custom loaders.
const files = {
  css: "public/style.css",
  js: "public/app.js",
  htmx: "public/vendor/htmx.min.js",
};
let source =
  "// Generated by bun run assets. Edit public/ files, then regenerate.\n";
for (const [name, path] of Object.entries(files)) {
  source += `export const ${name} = ${JSON.stringify(await Bun.file(path).text())};\n`;
}
await Bun.write(
  "src/assets.ts",
  await format(source, { parser: "typescript" }),
);
